		closesocket(sock);
		return NULL;
	}

	/* Verify status line */
	string line = recvline(sock);
	if (sscanf(line.c_str(), "HTTP/1.%*d %lu", &status) == 1 && status == 200) {
		/* Check for correct mime type and content length */
		content_length = 0;
		for (line = recvline(sock) ; line != "\r" && line != "" ; line = recvline(sock)) {
