			root["result"][ii]["Params"] = sParams;
			root["result"][ii]["Priority"] = itt.Priority;
			root["result"][ii]["SendAlways"] = itt.SendAlways;
			root["result"][ii]["CustomMessage"] = itt.CustomMessage;
			root["result"][ii]["ActiveSystems"] = itt.ActiveSystems;
