cms_contentinfo_create(krb5_context context,                          /* IN */
                       pkinit_plg_crypto_context plg_cryptoctx,       /* IN */
                       pkinit_req_crypto_context req_cryptoctx,       /* IN */
                       pkinit_identity_crypto_context id_cryptoctx,   /* IN */
                       int cms_msg_type,
                       unsigned char *data, unsigned int data_len,
                       unsigned char **out_data, unsigned int *out_data_len)
{
    krb5_error_code retval = ENOMEM;
    ASN1_OBJECT *oid = NULL;
    PKCS7 *p7 = NULL;
    unsigned char *p;

    /* Pick the correct oid for the eContentInfo. */
    oid = pkinit_pkcs7type2oid(plg_cryptoctx, cms_msg_type);
    if (oid == NULL)
        goto cleanup;
    retval = create_contentinfo(context, plg_cryptoctx, oid,
                                data, data_len, &p7);
    if (retval != 0)
        goto cleanup;
    *out_data_len = i2d_PKCS7(p7, NULL);
    if (!(*out_data_len)) {
        unsigned long err = ERR_peek_error();
        retval = KRB5KDC_ERR_PREAUTH_FAILED;
        krb5_set_error_message(context, retval, "%s\n",
                               ERR_error_string(err, NULL));
        pkiDebug("failed to der encode pkcs7\n");
        goto cleanup;
    }
    retval = ENOMEM;
    if ((p = *out_data = malloc(*out_data_len)) == NULL)
        goto cleanup;

    /* DER encode PKCS7 data */
    retval = i2d_PKCS7(p7, &p);
    if (!retval) {
        unsigned long err = ERR_peek_error();
        retval = KRB5KDC_ERR_PREAUTH_FAILED;
        krb5_set_error_message(context, retval, "%s\n",
                               ERR_error_string(err, NULL));
        pkiDebug("failed to der encode pkcs7\n");
        goto cleanup;
    }
    retval = 0;
cleanup:
    if (p7)
        PKCS7_free(p7);
    if (oid)
        ASN1_OBJECT_free(oid);
    return retval;
}

error::Error GLES2DecoderPassthroughImpl::DoDescheduleUntilFinishedCHROMIUM() {
  if (!gl::GLFence::IsSupported()) {
    return error::kNoError;
  }
  deschedule_until_finished_fences_.push_back(gl::GLFence::Create());

  if (deschedule_until_finished_fences_.size() == 1) {
    return error::kNoError;
  }

  DCHECK_EQ(2u, deschedule_until_finished_fences_.size());
  if (deschedule_until_finished_fences_[0]->HasCompleted()) {
    deschedule_until_finished_fences_.erase(
        deschedule_until_finished_fences_.begin());
    return error::kNoError;
  }

  TRACE_EVENT_ASYNC_BEGIN0(
      "cc", "GLES2DecoderPassthroughImpl::DescheduleUntilFinished", this);
  client()->OnDescheduleUntilFinished();
  return error::kDeferLaterCommands;
}

load_file(png_const_charp name, png_bytepp result)
{
 FILE *fp = tmpfile();

 if (fp != NULL)
 {
 FILE *ip = fopen(name, "rb");

 if (ip != NULL)
 {
 size_t total = 0;
 int ch;

 for (;;)
 {
            ch = getc(ip);
 if (ch == EOF) break;
            putc(ch, fp);
 ++total;
 }

 if (ferror(ip))
 {
            perror(name);
            fprintf(stderr, "%s: read error\n", name);
 (void)fclose(ip);
 }

 else
 {
 (void)fclose(ip);

 if (ferror(fp))
 {
               perror("temporary file");
               fprintf(stderr, "temporary file write error\n");
 }

 else
 {
               rewind(fp);

 if (total > 0)
 {
 /* Round up to a multiple of 4 here to allow an iCCP profile
                   * to be padded to a 4x boundary.
                   */
                  png_bytep data = malloc((total+3)&~3);

 if (data != NULL)
 {
 size_t new_size = 0;

 for (;;)
 {
                        ch = getc(fp);
 if (ch == EOF) break;
                        data[new_size++] = (png_byte)ch;
 }

 if (ferror(fp) || new_size != total)
 {
                        perror("temporary file");
                        fprintf(stderr, "temporary file read error\n");
                        free(data);
 }

 else
 {
 (void)fclose(fp);
 *result = data;
 return total;
 }
 }

 else
                     fprintf(stderr, "%s: out of memory loading file\n", name);
 }

 else
                  fprintf(stderr, "%s: empty file\n", name);
 }
 }
 }

 else
 {
         perror(name);
         fprintf(stderr, "%s: open failed\n", name);
 }

      fclose(fp);
 }

 else
      fprintf(stderr, "makepng: %s: could not open temporary file\n", name);

   exit(1);
 return 0;
}

